[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-pulmonology",
  "answer": "작년 자연기흉 병력 + 20대 마른 체형 + 오늘 한쪽 흉통은 재발성 기흉(가장 먼저) 과 폐색전증·급성 관상동맥 증후군·대동맥 박리 같은 즉시 배제 대상이 겹치는 조합입니다. 다만 현재 제공된 정보에는 호흡곤란 정도·흉통 양상·활력징후·산소포화도가 없어 \"재발성 기흉이다/아니다\"를 원격 텍스트로 확정할 수 없고, 판별력이 가장 큰 문진 하나(호흡곤란의 정도와 한쪽 흉통이 숨쉬거나 기침할 때 심해지는지)와 흉부 영상(흉부 X선, 필요시 CT)이 필요합니다.",
  "red_flag": {
    "present": true,
    "items": [
      { "id": "PU4", "evidence": "한쪽 흉통 + 자연기흉 병력(기흉 재발 시사 조합)", "basis": "history" },
      { "id": "PU1", "evidence": "호흡곤란 정도·말하기 가능 여부가 제공되지 않음 → 확인되지 않음이 아니라 '미확인'으로 두고, 위험 신호 존재 가능성 우선", "basis": "history" },
      { "id": "PU2", "evidence": "환자 제공 산소포화도 없음 → 저산소 여부 미확인", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "재발성 자연기흉",
      "icd10": "J93.1",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "20대 마른 체형(원발성 자연기흉의 전형적 체형)", "basis": "history" },
        { "text": "작년 자연기흉 병력(동측 재발 위험)", "basis": "history" },
        { "text": "오늘 한쪽 가슴 통증(흉막성 흉통 양상이면 부합)", "basis": "history" }
      ],
      "against": [
        { "text": "흉통의 호흡·기침 연관성, 호흡곤란 동반 여부가 제공되지 않음", "basis": "history" },
        { "text": "흉부 영상 소견 없음 — 진단 확정·배제 불가", "basis": "history" }
      ]
    },
    {
      "name": "폐색전증",
      "icd10": "I26",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "급성 한쪽 흉통 + 호흡기 증상 조합에서 감별 필요", "basis": "guideline" }
      ],
      "against": [
        { "text": "최근 수술·장거리 이동·다리 부종·장기 부동 여부 정보 없음", "basis": "history" },
        { "text": "20대 마른 체형은 통상 저위험", "basis": "history" }
      ]
    },
    {
      "name": "급성 관상동맥 증후군",
      "icd10": "I24.9",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "한쪽 흉통 단독 — 연령·체형상 전형적이지 않으나 원격에서는 배제 불가", "basis": "guideline" }
      ],
      "against": [
        { "text": "20대, 심혈관 위험인자 정보 없음", "basis": "history" }
      ]
    },
    {
      "name": "흉막·기관지·종격동 병변(예: 흉막 염증·종양·기관지 문제)",
      "icd10": "R09.1",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "지속성·비전형적 흉통에서 고려", "basis": "guideline" }
      ],
      "against": [
        { "text": "객혈·체중 감소·야간 발한·흡연력 정보 없음", "basis": "history" }
      ]
    },
    {
      "name": "근골격성 흉통(늑연골·근육·자세)",
      "icd10": "M79.1",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "젊은 성인의 한쪽 국소 흉통에서 흔함", "basis": "guideline" }
      ],
      "against": [
        { "text": "흉통의 압박 시 재현성·호흡 연관 여부 미확인", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "숨이 차서 문장을 끝까지 말하기 어렵거나 안정 시에도 호흡곤란이 있는지, 그리고 통증이 숨을 깊게 들이쉬거나 기침할 때 더 심해지는지 (있다/없다만)"
  ],
  "suggested_tests": [
    { "name": "흉부 X선(양측 폐야, 흉막선 확인)", "purpose": "기흉·흉막 액·폐 병변 확인", "urgency": "now", "basis": "guideline" },
    { "name": "환자 측정 산소포화도 및 활력징후(맥박·호흡수·혈압)", "purpose": "저산소·혈역학 이상 확인", "urgency": "now", "basis": "guideline" },
    { "name": "필요 시 흉부 CT(흉부 X선으로 애매하거나 지속 흉통일 때)", "purpose": "소량 기흉·소수포·폐색전·기타 병변 감별", "urgency": "24h", "basis": "guideline" },
    { "name": "심전도·트로포닌(흉통 양상이 비전형이거나 지속될 때)", "purpose": "급성 관상동맥 증후군 배제", "urgency": "now", "basis": "guideline" },
    { "name": "호흡기내과 진료(대면 진찰 — 청진·타진)", "purpose": "기흉·흉막 마찰음·편측 호흡음 감소 확인", "urgency": "now", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "referral", "description": "흉통 + 기흉 병력 → 응급실 또는 호흡기내과 즉시 평가(원격으로는 배제 불가)", "basis": "guideline" },
    { "kind": "self_care", "description": "확인 전까지 격한 활동·비행·잠수·흡연 회피, 증상 악화 시 즉시 응급실", "basis": "guideline" }
  ],
  "handoff": { "better_specialty": "kdoctor-emergency", "reason": "PU4(한쪽 흉통 + 기흉 병력) 및 PU1·PU2 미확인 → 응급 평가 우선. 재발성 기흉이 확인되면 kdoctor-thoracic-surgery(재발성 기흉의 수술적 평가), 폐색전 가능성 배제 필요 시 응급 협진." },
  "confidence": { "clinical": 2, "information": 1 },
  "warnings": [
    "원격 텍스트 소견 — 청진·타진·영상 없이 기흉을 확정하거나 배제할 수 없음.",
    "산소포화도 수치는 손톱 도포·저관류·기기 오차로 부정확할 수 있음 — 환자·기관 판정을 인용할 것.",
    "마른 체형·젊은 연령은 기흉 재발 위험을 높이는 배경이지 진단 근거가 아님 — 흉부 영상 없이는 재발성 기흉으로 단정하지 않는다.",
    "흉통이 20분 이상 지속되거나 식은땀·실신·심계항진 동반 시 즉시 응급실."
  ]
}
[/SPECIALIST_FINDING]

